/**
 * Opcjonalny adapter OpenCascade.js.
 *
 * OCCT jest celowo ładowany dopiero na żądanie. Dzięki temu zwykłe
 * modelowanie (Manifold) i start aplikacji nie płacą kosztu ~66 MB pliku WASM,
 * a instalacja mobilna pozostaje lekka. Moduł nie zmienia istniejącego
 * renderera ani historii sceny; służy jako bezpieczny punkt wejścia dla
 * operacji B-rep, gdy użytkownik świadomie włączy tę funkcję.
 */

export type OpenCascadeKernel = Record<string, unknown>;

let kernelPromise: Promise<OpenCascadeKernel> | null = null;

export function loadOpenCascadeKernel(): Promise<OpenCascadeKernel> {
  if (!kernelPromise) {
    // Importujemy sam loader JS, a plik WASM trzymamy jako statyczny asset.
    // Główny entrypoint npm próbuje importować `.wasm` jako moduł ESM,
    // czego Vite/Rolldown nie obsługuje w trybie produkcyjnym.
    kernelPromise = import("opencascade.js/dist/opencascade.wasm.js")
      .then(module => {
        const Loader = (module as { default?: new (options: Record<string, unknown>) => Promise<OpenCascadeKernel> }).default;
        if (!Loader) throw new Error("Brak loadera OpenCascade.js");
        return new Loader({ locateFile: (path: string) => path.endsWith(".wasm") ? `${import.meta.env.BASE_URL}occt/${path}` : path }) as unknown as Promise<OpenCascadeKernel>;
      })
      .catch(error => {
        kernelPromise = null;
        throw new Error(`Nie udało się załadować opcjonalnego silnika B-rep: ${String(error)}`);
      });
  }
  return kernelPromise;
}

export function isOpenCascadeLoading(): boolean {
  return kernelPromise !== null;
}

export function resetOpenCascadeKernel(): void {
  kernelPromise = null;
}
