function cameraBounds() {
  const box = model ? new THREE.Box3().setFromObject(model) : new THREE.Box3();
  if (box.isEmpty()) {
    const center = controls.target.clone();
    box.set(center.clone().addScalar(-50), center.clone().addScalar(50));
  }
  return box;
}
function cameraView(direction: THREE.Vector3, buttonId: string, label: string) {
  const box = cameraBounds();
  const center = box.getCenter(new THREE.Vector3());
  const size = box.getSize(new THREE.Vector3());
  const radius = Math.max(20, size.length() * .5);
  const dir = direction.clone().normalize();
  const distance = Math.max(80, radius / Math.sin(THREE.MathUtils.degToRad(camera.fov * .5)) * 1.18);
  controls.target.copy(center);
  // Przy widoku góra/dół oś Z jest równoległa do kierunku patrzenia,
  // więc jako pion ekranu trzeba użyć osi Y.
  camera.up.set(0, 0, Math.abs(dir.z) > .98 ? 0 : 1);
  if (Math.abs(dir.z) > .98) camera.up.set(0, 1, 0);
  camera.position.copy(center).add(dir.multiplyScalar(distance));
  camera.near = Math.max(.01, distance / 1000);
  camera.far = Math.max(5000, distance * 12);
  camera.lookAt(center);
  camera.updateProjectionMatrix();
  controls.update();
  for (const id of ["view-main","view-iso","view-front","view-right","view-top"])
    document.querySelector(`#${id}`)?.classList.toggle("active", id === buttonId);
  const cubeView:Record<string,string>={"view-top":"cube-top","view-front":"cube-front","view-right":"cube-right"};
  for(const id of ["cube-top","cube-front","cube-right","cube-left","cube-back","cube-bottom"])document.querySelector(`#${id}`)?.classList.toggle("active",cubeView[buttonId]===id);
  setStatus(`Widok: ${label}`, "Model wycentrowany · kamera ustawiona");
}
