async function printAutoOrient() {
  const part = requireEditablePart("orientacja"); if (!part) return;
  const mesh = partObject(part.id);
  if (!mesh) { setStatus("Brak podglądu", "Poczekaj na render sceny"); return; }
  rememberScene();
  const base = new THREE.Matrix4().fromArray(part.matrix);
  const rots = [new THREE.Euler(0, 0, 0), new THREE.Euler(Math.PI / 2, 0, 0), new THREE.Euler(-Math.PI / 2, 0, 0), new THREE.Euler(0, Math.PI / 2, 0), new THREE.Euler(0, -Math.PI / 2, 0), new THREE.Euler(0, Math.PI, 0)];
  let best: THREE.Matrix4 | null = null, bestH = Infinity;
  for (const e of rots) {
    const m = new THREE.Matrix4().makeRotationFromEuler(e).multiply(base);
    mesh.updateWorldMatrix(true, false);
    const probe = mesh.clone(); probe.applyMatrix4(new THREE.Matrix4().makeRotationFromEuler(e));
    const box = new THREE.Box3().setFromObject(probe);
    const h = box.max.z - box.min.z;
    if (h < bestH) { bestH = h; best = m; }
    probe.geometry.dispose();
  }
  if (best) part.matrix = best.toArray();
  await renderStudioScene(false); updateHistoryButtons(); scheduleRecovery();
  setStatus("Zorientowano", `Najniższa wysokość ${bestH.toFixed(1)} mm · stabilna podstawa do druku`);
}
