const clipState = { plane: new THREE.Plane(new THREE.Vector3(0, 0, -1), 0), helper: null as THREE.Mesh | null };
function updateClip() {
  const enabled = document.querySelector<HTMLInputElement>("#clip-enabled")!.checked;
  renderer.localClippingEnabled = true;
  renderer.clippingPlanes = enabled ? [clipState.plane] : [];
  const axis = document.querySelector<HTMLSelectElement>("#clip-axis")!.value;
  const offset = Number(document.querySelector<HTMLInputElement>("#clip-offset")!.value) || 0;
  const n = axis === "x" ? new THREE.Vector3(-1, 0, 0) : axis === "y" ? new THREE.Vector3(0, -1, 0) : new THREE.Vector3(0, 0, -1);
  if ((updateClip as { flip?: boolean }).flip) n.negate();
  clipState.plane.normal.copy(n); clipState.plane.constant = offset;
  if (clipState.helper) { scene.remove(clipState.helper); clipState.helper.geometry.dispose(); (clipState.helper.material as THREE.Material).dispose(); clipState.helper = null; }
  if (enabled) {
    const size = Math.max(60, camera.position.distanceTo(controls.target) * .8);
    clipState.helper = new THREE.Mesh(new THREE.PlaneGeometry(size, size), new THREE.MeshBasicMaterial({ color: 0x41c8ff, transparent: true, opacity: .08, side: THREE.DoubleSide, depthWrite: false }));
    const onPlane = controls.target.clone().addScaledVector(n, -(n.dot(controls.target) + offset));
    clipState.helper.position.copy(onPlane);
    clipState.helper.lookAt(onPlane.clone().add(n.clone().negate()));
    clipState.helper.renderOrder = 14; clipState.helper.userData.surfaceContour = true; scene.add(clipState.helper);
  }
  setStatus(enabled ? "Przekrój aktywny" : "Przekrój wyłączony", enabled ? "Suwak tnie podgląd — geometria i eksport bez zmian" : "");
}
async function alignSelection() {
  const base = activePart();
  const others = selectedPartsForPattern().filter(p => p.id !== base?.id);
  if (!base || !others.length) { setStatus("Brak pary", "Zaznacz co najmniej 2 obiekty (aktywny to baza)"); return; }
  rememberScene();
  const axis = document.querySelector<HTMLSelectElement>("#align-axis")!.value as "x" | "y" | "z";
  const mode = document.querySelector<HTMLSelectElement>("#align-mode")!.value as "min" | "center" | "max";
  const baseBox = partWorldBox(base);
  const ref = mode === "min" ? baseBox.min[axis] : mode === "max" ? baseBox.max[axis] : baseBox.getCenter(new THREE.Vector3())[axis];
  for (const part of others) {
    const box = partWorldBox(part);
    const cur = mode === "min" ? box.min[axis] : mode === "max" ? box.max[axis] : box.getCenter(new THREE.Vector3())[axis];
    const delta = new THREE.Vector3(); delta[axis] = ref - cur;
    part.matrix = new THREE.Matrix4().makeTranslation(delta.x, delta.y, delta.z).multiply(new THREE.Matrix4().fromArray(part.matrix)).toArray();
  }
  await renderStudioScene(false); updateHistoryButtons(); scheduleRecovery();
  setStatus("Wyrównano", `${others.length} obiektów do ${mode} osi ${axis.toUpperCase()} bazy ${base.name}`);
}
