let explodeFactor = 0;
function applyExplode(quiet = false) {
  explodeFactor = Number(document.querySelector<HTMLInputElement>("#explode-factor")!.value) || 0;
  if (!model) return;
  const sceneBox = new THREE.Box3().setFromObject(model);
  if (sceneBox.isEmpty()) return;
  const center = sceneBox.getCenter(new THREE.Vector3());
  model.children.forEach(child => {
    const partId = child.userData.partId as string | undefined;
    if (!partId || !child.userData.partCenter) return;
    const partCenter = new THREE.Vector3(...(child.userData.partCenter as number[]));
    const dir = partCenter.clone().sub(center); if (dir.lengthSq() < 1e-6) dir.set(0, 0, 1); dir.normalize();
    const base = new THREE.Matrix4().fromArray(studioParts.find(p => p.id === partId)?.matrix ?? IDENTITY_MATRIX);
    const withExplode = new THREE.Matrix4().makeTranslation(dir.x * explodeFactor, dir.y * explodeFactor, dir.z * explodeFactor).multiply(base);
    const srcCenter = new THREE.Vector3(...(child.userData.partCenter as number[]));
    child.matrix.copy(withExplode.multiply(new THREE.Matrix4().makeTranslation(srcCenter.x, srcCenter.y, srcCenter.z)));
    child.matrix.decompose(child.position, child.quaternion, child.scale);
  });
  if (!quiet) setStatus(explodeFactor > 0 ? "Rozstrzał złożenia" : "Złożenie", explodeFactor > 0 ? `${explodeFactor} mm od środka · tylko podgląd, eksport bez zmian` : "");
}
