  try{root=await buildExportScene();if(kind==="obj"){const text=new OBJExporter().parse(root);await downloadRaw(new Blob([text],{type:"text/plain;charset=utf-8"}),"skaner-studio-scena.obj");}else if(kind==="stl"){const data=new STLExporter().parse(root,{binary:true});const buffer=data instanceof DataView?data.buffer.slice(data.byteOffset,data.byteOffset+data.byteLength):new TextEncoder().encode(String(data)).buffer;await downloadRaw(new Blob([buffer],{type:"model/stl"}),"skaner-studio-scena.stl");}else{const data=await new GLTFExporter().parseAsync(root,{binary:true,onlyVisible:true});if(!(data instanceof ArrayBuffer))throw new Error("Eksporter nie zwrócił binarnego GLB");await downloadRaw(new Blob([data],{type:"model/gltf-binary"}),"skaner-studio-scena.glb");}if(!appleMobile())setStatus("Eksport gotowy",`${kind.toUpperCase()} · cała widoczna scena · transformacje świata zachowane`);}catch(error){setStatus("Błąd eksportu",error instanceof Error?error.message:String(error));}finally{if(root)disposeRenderedModel(root);}
