const workspaceTools:Record<typeof tabs[number],Set<string>>={
  model:new Set(["select","draw","primitive","move","rotate","scale","face","area","surface-add","array","copy","mirror","delete","undo","redo"]),
  sculpt:new Set(["select","sculpt","smooth","delete","undo","redo"]),
  curves:new Set(["select","draw","move","rotate","scale","delete","undo","redo"]),
  cad:new Set(["select","primitive","move","rotate","scale","face","area","boolean","array","copy","mirror","delete","undo","redo"]),
  detail:new Set(["select","face","measure","print","smooth","delete","undo","redo"]),
  export:new Set(["select","delete","undo","redo"])
};
function syncWorkspaceTools(workspace:typeof tabs[number]){
  const allowed=workspaceTools[workspace];
  for(const button of document.querySelectorAll<HTMLButtonElement>(".modeling-tools button[id^='tool-']")){
    // The primitive button has a descriptive DOM id (tool-add-primitive),
    // while the tool state is named simply "primitive". Keep the alias here
    // so changing workspace tabs never hides the basic solid-creation tool.
    const rawId=button.id.replace(/^tool-/,'');
    const id=rawId==="add-primitive"?"primitive":rawId;
    button.hidden=!allowed.has(id);
  }
  document.querySelector(".modeling-tools")?.setAttribute("aria-label",`Narzędzia: ${workspace}`);
}
function selectTab(selected: typeof tabs[number]) {
  for (const name of tabs) document.querySelector(`#tab-${name}`)?.classList.toggle("active", name === selected);
  document.querySelector<HTMLElement>("#export-workspace")!.hidden = selected !== "export";
  syncWorkspaceTools(selected);
  if(selected!=="export"){const tools={model:"select",sculpt:"sculpt",curves:"draw",cad:"primitive",detail:"surfaceAdd"} as const;selectModelingTool(tools[selected]);}
  if (selected === "export") setStatus("Eksport", latest ? "Wybierz OBJ albo STL" : "Najpierw wygeneruj albo wczytaj model");
}

