// Smooth is the one brush that should preserve volume instead of shrinking
// the surface toward its neighbours. Keep the fast local sculpt kernel for
// every mode, then apply a short Taubin pass only to the affected result.
// This removes banding without the rubbery Laplacian shrink that was visible
// on small mobile strokes.
function sculpt(d:MeshData,p:any){
  const output=sculptCore(d,p);
  if(String(p.mode)==="smooth"&&output.d.f.length<120000){
    const strength=THREE.MathUtils.clamp(Math.abs(Number(p.strength)||.5),.05,.65);
    output.d=taubinRelax(output.d,2,strength,false,180);
  }
  return output;
}
